yakit.AutoInitYakit()
log.setLevel("info")
targets = cli.String("targets",cli.setRequired(true))
thread := cli.Int("thread")
cli.check()
targets = str.RemoveRepeat(str.ParseStringToLines(targets))
//表格函数
yakit.EnableTable("IP反查域名表", ["target", "反查域名","history"])
domaintable = func(target,domain,history) {
    data = make(map[string]var)
    data["target"] = target
    data["反查域名"] = domain
    data["history"] = history
    yakit.TableData("IP反查域名表", data)
}
/*
IP反查
*/
func reverseip(target,swg){
    swg.Add()
   go func{
    defer swg.Done()
        defer func{
            recover()
        }
        if !str.EndsWith(target,"/"){
            target = target +"/"
        }
        url = "https://dns.aizhan.com/"+target
        res,_:= poc.Get(url, poc.appendHeader("Referer", "https://dns.aizhan.com/"))~
        rspRaw := res.GetBody()
        Rsp := string(rspRaw)
        doc := xpath.LoadHTMLDocument(Rsp)~
        domain = []
        domainnodes := xpath.Find(doc, `//*[@class="domain"]`)
        for _, node := range domainnodes {
            if _ == 0{
                continue
            }
            t = str.TrimSpace(xpath.InnerText(node))
            domain = append(domain,t)
        }
        ip138 = "https://site.ip138.com/"+target
        res1,_ = poc.Get(ip138)~
        res1raw = res1.GetBody()
        doc1 = xpath.LoadHTMLDocument(res1raw)~
        history = xpath.Find(doc1, `//ul/li`)
        historyTable =[]string{}
        flag = false 
        for _,node := range history{
            if "绑定过的域名如下" in str.TrimSpace(xpath.InnerText(node)){
                flag=true
                continue
            }
            if flag{
                matchData = re.FindSubmatchAll(str.TrimSpace(xpath.InnerText(node)), `(\d{4}-\d{2}-\d{2}-----\d{4}-\d{2}-\d{2})(.*)`)
                var s
                for data  in matchData{
                    s = data[1]+"\t"+data[2]+"\n"
                }
                historyTable = append(historyTable,s)
            }
            if "最新域名查询" in str.TrimSpace(xpath.InnerText(node)){
                flag = false
                historyTable = historyTable[:len(historyTable)-1]
                break
            }
        }
        for i,j := range domain{
           domaintable(re.ExtractIP(target),j,historyTable)
        }
        if len(domain)==0{
            domaintable(re.ExtractIP(target), "",historyTable)
        }
    }
}
swg = sync.NewSizedWaitGroup(thread)
for _,target :=range targets{
    reverseip(target,swg)
}
swg.Wait()
